import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${select({id: "fd",label: "flex-direction",value: "row",options: [{ label: "row", value: "row" },{ label: "row-reverse", value: "row-reverse" },{ label: "column", value: "column" },{ label: "column-reverse", value: "column-reverse" }]})}${select({id: "fw",label: "flex-wrap",value: "nowrap",options: [{ label: "nowrap", value: "nowrap" },{ label: "wrap", value: "wrap" },{ label: "wrap-reverse", value: "wrap-reverse" }]})}${select({id: "jc",label: "justify-content",value: "flex-start",options: [{ label: "flex-start", value: "flex-start" },{ label: "center", value: "center" },{ label: "flex-end", value: "flex-end" },{ label: "space-between", value: "space-between" },{ label: "space-around", value: "space-around" },{ label: "space-evenly", value: "space-evenly" }]})}${select({id: "ai",label: "align-items",value: "stretch",options: [{ label: "stretch", value: "stretch" },{ label: "flex-start", value: "flex-start" },{ label: "center", value: "center" },{ label: "flex-end", value: "flex-end" },{ label: "baseline", value: "baseline" }]})}</div>`,generate(root) {const fd = root.querySelector("#fd").value;const fw = root.querySelector("#fw").value;const jc = root.querySelector("#jc").value;const ai = root.querySelector("#ai").value;const css = `display: flex;\nflex-direction: ${fd};\nflex-wrap: ${fw};\njustify-content: ${jc};\nalign-items: ${ai};`;const html = `<div class="flex-container">\n <div>Item 1</div>\n <div>Item 2</div>\n <div>Item 3</div>\n</div>`;const preview = `<div style="display:flex;flex-direction:${fd};flex-wrap:${fw};justify-content:${jc};align-items:${ai};gap:8px;padding:8px;border:1px solid #e5e7eb;border-radius:4px;min-height:60px"><div style="background:#ef4444;color:#fff;padding:12px 16px;border-radius:4px;font-weight:700">1</div><div style="background:#3b82f6;color:#fff;padding:12px 16px;border-radius:4px;font-weight:700">2</div><div style="background:#22c55e;color:#fff;padding:12px 16px;border-radius:4px;font-weight:700">3</div></div>`;return { output: `${css}\n\n<!-- HTML -->\n${html}`, preview };}};